from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit
import hashlib
import json
import re

root = Path('products/services/nz-gets-offline-data-quote')
source = (root / 'raw/gets-index.html').read_bytes()
source_url = 'https://www.gets.govt.nz/ExternalIndex.htm'
expected_hash = 'aa0d5af6c35cb88ab64ca21c140eb9eecb3af9410cab59395be366385aca3f30'
source_hash = hashlib.sha256(source).hexdigest()
assert source_hash == expected_hash, 'GETS capture does not match the fetch receipt'

class IndexParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.row = None
        self.anchor = None
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.row = {'text': [], 'links': []}
        if tag == 'a':
            self.anchor = {'href': dict(attrs).get('href') or '', 'text': []}

    def handle_data(self, data):
        if self.row is not None:
            self.row['text'].append(data)
        if self.anchor is not None:
            self.anchor['text'].append(data)

    def handle_endtag(self, tag):
        if tag == 'a' and self.anchor is not None:
            anchor = self.anchor
            self.anchor = None
            url = urljoin(source_url, anchor['href'])
            parts = urlsplit(url)
            if parts.scheme == 'https' and parts.netloc == 'www.gets.govt.nz' and parts.path.lower().endswith('/externaltenderdetails.htm'):
                link = {'url': url, 'link_text': ' '.join(''.join(anchor['text']).split())}
                if self.row is None:
                    self.links.append(link)
                else:
                    self.row['links'].append(link)
        if tag == 'tr' and self.row is not None:
            row_text = ' '.join(' '.join(self.row['text']).split())
            self.links.extend(dict(link, index_row=row_text) for link in self.row['links'])
            self.row = None

parser = IndexParser()
parser.feed(source.decode('utf-8'))
parser.close()
pattern = re.compile(r'\b(?:reconcil\w*|migrat\w*|export\w*|validat\w*|data quality|data cleansing|data conversion|data mapping|data integrity|catalogu?e|spreadsheet|CSV)\b', re.I)
unique = {link['url']: link for link in parser.links}
pointers = [dict(link, matched_terms=sorted(set(pattern.findall(link.get('index_row', link['link_text']))))) for link in unique.values()]
result = {'source': source_url, 'source_sha256': source_hash, 'distinct_notice_links': len(unique), 'keyword_pointers': [link for link in pointers if link['matched_terms']], 'all_notice_links': list(unique.values()), 'scope': 'One GETS index capture. Links and keyword matches are discovery only. Even an empty extraction does not establish whether GETS has open notices or a suitable buyer request.'}
output = root / 'director-index-screen.json'
output.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
readback = json.loads(output.read_text(encoding='utf-8'))
assert readback == result
print(json.dumps({key: readback[key] for key in ('source_sha256', 'distinct_notice_links', 'keyword_pointers')}, ensure_ascii=False))
